% toon0512 -- Lincoln Refinement Scheme%%  Now show Abe as the upper left corner of a 128*128 %  two-dimensional wavelet transform.%	HonestAbe = ReadImage('Lincoln');	CrudeAbe  = HCoarsen2d(HonestAbe,1);%	BigAbe    = zeros(128,128);	BigAbe(1:32,1:32) = CrudeAbe;	image(BigAbe);	axis('image')	colormap(gray(32));	title('Extension to 128*128 in Wavelet Domain');        %   % Part of WaveLab Version 802% Built Sunday, October 3, 1999 8:52:27 AM% This is Copyrighted Material% For Copying permissions see COPYING.m% Comments? e-mail wavelab@stat.stanford.edu%       